
CREATE DATABASE BankSystem 
go
USE BankSystem

CREATE TABLE Customers (
	CustomerID int not null Primary Key identity(1, 1),
	FullName varchar(50) not null,
	DOB date,
	Email varchar(50),
	PhoneNumber varchar(30), 
	Address varchar(50),
	NationalID varchar(20) not null Unique, 
	TaxID varchar(20), 
	EmploymentStatus varchar(30), 
	AnnualIncome decimal(15, 2),
	CreatedAt DateTime Default Getdate(), 
	UpdatedAt DateTime Default Getdate()
)

CREATE TABLE Branches (
	BranchID int Primary Key identity(1, 1),
	BranchName varchar(30), 
	Address varchar(50), 
	City varchar(20), 
	State varchar(20), 
	Country varchar(20),
	ManagerID int,  
	ContactNumber varchar(20)
)

CREATE TABLE Employees (
	EmployeeID int not null Primary Key identity(1, 1), 
	BranchID int Foreign Key References Branches(BranchID),
	FullName varchar(30), 
	Position varchar(20), 
	Department varchar(20),
	Salary decimal(15, 2), 
	HireDate date, 
	Status varchar (20)
)


CREATE TABLE Accounts (
	AccountID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	AccountType varchar(30),                                    --(Savings, Checking, Business, etc.)
	Balance decimal(15, 2), 
	Currency varchar(10), 
	Status varchar(20),
	BranchID int Foreign Key References Branches(BranchID),  
	CreatedDate DateTime Default Getdate()
)

CREATE TABLE Transactions (
	TransactionID int Primary Key identity(1, 1), 
	AccountID int Foreign Key References Accounts(AccountID),
	TransactionType varchar(20) check (TransactionType in ('Deposit', 'Withdrawal', 'Transfer', 'Payment')), 
	Amount decimal(15, 2), 
	Currency varchar(10), 
	Date date, 
	Status varchar(20), 
	ReferenceNo varchar(30)
)

CREATE TABLE CreditCards (
	CardID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	CardNumber varchar(20) Unique, 
	CardType varchar(30), 
	CVV char(4), 
	ExpiryDate date, 
	Limit decimal(15, 2), 
	Status varchar(20)
)

CREATE TABLE CreditCardTransactions (
	TransactionID int Primary Key
	Foreign Key References Transactions(TransactionID), 
	CardID int Foreign Key References CreditCards(CardID),
	Merchant varchar(30), 
	Amount decimal(15, 2), 
	Currency varchar(10), 
	Date date, 
	Status varchar(20)
)

CREATE TABLE OnlineBankingUsers (
	UserID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	Username varchar(30), 
	PasswordHash varchar(255), 
	LastLogin DateTime Default Getdate()
)

CREATE TABLE BillPayments (
	PaymentID int Primary Key identity(1, 1),                 
	CustomerID int Foreign Key References Customers(CustomerID),
	BillerName varchar(30), 
	Amount decimal(15, 2), 
	Date date, 
	Status varchar(20)
)

CREATE TABLE MobileBankingTransactions (
	TransactionID int Primary Key
	Foreign Key References Transactions(TransactionID), 
	CustomerID int Foreign Key References Customers(CustomerID),
	DeviceID varchar(30), 
	AppVersion varchar(30), 
	TransactionType varchar(30), 
	Amount decimal(15, 2), 
	Date date
)

CREATE TABLE Loans (
	LoanID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	LoanType varchar(20) check (LoanType in ('Mortgage', 'Personal', 'Auto', 'Business')),
	Amount decimal(15, 2), 
	InterestRate decimal(5, 2), 
	StartDate Date, 
	EndDate Date , 
	Status varchar(20)
)

CREATE TABLE LoanPayments (
	PaymentID int Primary Key identity(1, 1),        
	LoanID int Foreign Key References Loans(LoanID),
	AmountPaid Decimal(15, 2), 
	PaymentDate Date, 
	RemainingBalance decimal(15, 2)
)

CREATE TABLE CreditScores (
	CustomerID int Foreign Key References Customers(CustomerID), 
	CreditScore int, 
	UpdatedAt DateTime Default Getdate() 
)

CREATE TABLE DebtCollection (
	DebtID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	AmountDue Decimal(15, 2), 
	DueDate Date, 
	CollectorAssigned int Foreign Key References Employees(EmployeeID)
)

CREATE TABLE KYC (
	KYCID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	DocumentType varchar(30), 
	DocumentNumber varchar(20), 
	VerifiedBy int Foreign Key References Employees(EmployeeID)
)

CREATE TABLE FraudDetection (
	FraudID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	TransactionID int Foreign Key References Transactions(TransactionID), 
	RiskLevel varchar(20), 
	ReportedDate DateTime
)

CREATE TABLE AML (
	CaseID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	CaseType varchar(20), 
	Status varchar(20), 
	InvestigatorID int
)

CREATE TABLE RegulatoryReports (
	ReportID int Primary Key identity(1, 1), 
	ReportType varchar(20), 
	SubmissionDate date
)

CREATE TABLE Departments (
	DepartmentID int Primary key identity(1, 1), 
	DepartmentName varchar(30), 
	ManagerID int Foreign Key References Employees(EmployeeID)
) 

CREATE TABLE Salaries (
	SalaryID int Primary Key identity(1, 1),
	EmployeeID int Foreign Key References Employees(EmployeeID),
	BaseSalary Decimal (10, 2),
	Bonus Decimal(10, 2), 
	Deductions Decimal(10, 2), 
	PaymentDate DateTime 
)

CREATE TABLE EmployeeAttendance (
	AttendanceID int Primary Key identity(1, 1), 
	EmployeeID int Foreign Key References Employees(EmployeeID),
	CheckInTime DateTime,
	CheckOutTime DateTime, 
	TotalHours decimal(5, 2)
)

CREATE TABLE Investments (
	InvestmentID int Primary Key identity(1, 1),
	CustomerID int Foreign Key References Customers(CustomerID),
	InvestmentType varchar(20), 
	Amount decimal(10, 2), 
	ROI decimal(6, 2), 
	MaturityDate date
)

CREATE TABLE StockTradingAccounts (
	AccountID int Primary Key
	Foreign Key References Accounts(AccountID), 
	CustomerID int Foreign Key References Customers(CustomerID),
	BrokerageFirm varchar(30), 
	TotalInvested decimal(15, 2), 
	CurrentValue decimal(15, 2)
)

CREATE TABLE ForeignExchange (
	FXID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	CurrencyPair varchar(10), 
	ExchangeRate decimal(15, 5), 
	AmountExchanged decimal(15, 2)
)

CREATE TABLE InsurancePolicies (
	PolicyID int Primary Key identity(1, 1), 
	CustomerID int Foreign Key References Customers(CustomerID),
	InsuranceType varchar(20), 
	PremiumAmount decimal(15, 2), 
	CoverageAmount decimal(15, 2)
)

CREATE TABLE Claims (
	ClaimID int Primary Key identity(1, 1), 
	PolicyID int Foreign Key References InsurancePolicies(PolicyID),
	ClaimAmount decimal(15, 2), 
	Status varchar(20),
	FiledDate date
)

CREATE TABLE UserAccessLogs (
	LogID int Primary Key identity(1, 1), 
	UserID int Foreign Key References OnlineBankingUsers(UserID),
	ActionType varchar(20), 
	Timestamp DateTime Default Getdate()
)

CREATE TABLE CyberSecurityIncidents (
	IncidentID int Primary Key identity(1, 1), 
	AffectedSystem varchar(30), 
	ReportedDate date, 
	ResolutionStatus varchar(20)
)

CREATE TABLE Merchants (
	MerchantID int Primary Key identity(1, 1), 
	MerchantName varchar(30), 
	Industry varchar(30), 
	Location varchar(30), 
	CustomerID int Foreign Key References Customers(CustomerID)
)

CREATE TABLE MerchantTransactions (
	TransactionID int Primary Key
	Foreign Key References Transactions(TransactionID),    
	MerchantID int Foreign Key References Merchants(MerchantID),
	Amount decimal(15, 2), 
	PaymentMethod varchar(20), 
	Date date
)

