--KPI 

-- 1 - Top 3 customers with the highest total balance across all their accounts

SELECT top 3
	c.CustomerID, 
	c.FullName, 
	sum(
	case 
	when a.Currency='USD' then a.Balance*12.100
	when a.Currency='EUR' then a.Balance*13.800
	else a.Balance end
	) as umumiy_balans
FROM Accounts a
	join Customers c
	on a.CustomerID=c.CustomerID
	group by c.CustomerID, c.FullName
	order by umumiy_balans desc


-- 2 - Customers with more than one active loan

SELECT
	l.CustomerID,
	c.FullName,
	count(l.CustomerID) as kreditlar_soni,
	sum(l.Amount) as umumiy_kredit
FROM Loans l
	join Customers c
	on l.CustomerID=c.CustomerID
	where l.Status='Active'
	group by l.CustomerID, c.FullName
	having count(l.CustomerID)>1


-- 3 - Transactions flagged as fraud

SELECT 
	f.FraudID,
	c.FullName,
	f.TransactionID,
	t.Amount,
	t.Currency,
	f.RiskLevel,
	t.Status
FROM FraudDetection f
	join Transactions t
	on f.TransactionID=t.TransactionID
	join Customers c
	on f.CustomerID=c.CustomerID
	order by f.FraudID


-- 4 - Total loan amount issued by each branch

; with filial_jami_kreditlar as(
SELECT
	b.BranchID,
	sum(Amount) as jami_kreditlar
FROM Loans l
	join Accounts a
	on l.CustomerID=a.CustomerID
	join Branches b
	on a.BranchID=b.BranchID
	group by b.BranchID
)
SELECT 
	f.BranchID,
	b.BranchName,
	b.City,
	f.jami_kreditlar
FROM filial_jami_kreditlar f
	join Branches b
	on f.BranchID=b.BranchID


-- 5 - Customers who made multiple large (over $10,000) transactions within a short time (less than 1 hour)

-- Step 1: change the column type from DATE to DATETIME
ALTER TABLE Transactions
ALTER COLUMN Date DATETIME;
GO

-- Step 2: add a RANDOM hour/minute/second to each row
UPDATE Transactions
SET Date = DATEADD(SECOND, ABS(CHECKSUM(NEWID())) % 86400, Date);
GO
