; with katta_tranzaksiya as (
SELECT 
	t.TransactionID,
	c.CustomerID,
	c.FullName,
	t.Date,
	case 
	when t.Currency='UZS' then cast(t.Amount/12.100 as decimal (10, 2))
	when t.Currency='EUR' then cast(t.Amount/1.14 as decimal(10, 2))
	else Amount 
	end  as usd_amount
FROM Transactions t
	join Accounts a
	on t.AccountID=a.AccountID
	join Customers c
	on a.CustomerID=c.CustomerID
), vaqt_farqi as (
SELECT *,
	lag(Date) over(partition by customerid order by date) as oldingi_vaqt
FROM katta_tranzaksiya
	where usd_amount>100000
)
SELECT * 
FROM vaqt_farqi
	where DATEDIFF(MINUTE, oldingi_vaqt, Date)<60


-- 6 - Customers who made transactions from different countries within 10 minutes (a typical fraud signal)

SELECT 
	*
FROM Transactions

ALTER TABLE Transactions
ADD Country VARCHAR(30);

UPDATE Transactions
SET Country = 
    CASE ABS(CHECKSUM(NEWID())) % 6
        WHEN 0 THEN 'Uzbekistan'
        WHEN 1 THEN 'USA'
        WHEN 2 THEN 'UK'
        WHEN 3 THEN 'UAE'
        WHEN 4 THEN 'Kazakhstan'
        WHEN 5 THEN 'Turkey'
    END;


;with Tranzaksiyalar as (
SELECT
	a.CustomerID,
	t.TransactionID,
	t.Date,
	t.Country,
	lag(t.Date) over (partition by a.CustomerID order by t.Date) as oldingi_vaqt,
	lag(t.Country) over (partition by a.CustomerID order by t.Date) as oldingi_davlat
FROM Transactions t
	join Accounts a
	on t.AccountID=a.AccountID
)
SELECT
	CustomerID,
	TransactionID,
	oldingi_davlat,
	Country,
	oldingi_vaqt,
	Date
FROM Tranzaksiyalar
	where DATEDIFF(MINUTE, oldingi_vaqt, Date)<10
	and Country <> oldingi_davlat
	order by CustomerID

